const path = require('path');
const fs = require('fs');
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST,
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  max: 10,
  statement_timeout: 30000
});

const TEMPLATES_DIR = '/var/task/templates';

async function logAccess(userId, templateName, action) {
  const client = await pool.connect();
  try {
    await client.query(
      'INSERT INTO access_log (user_id, resource, action, ts) VALUES ($1, $2, $3, NOW())',
      [userId, templateName, action]
    );
  } finally {
    client.release();
  }
}

async function getTemplateMetadata(templateName) {
  const client = await pool.connect();
  try {
    const result = await client.query(
      'SELECT id, name, version, content_hash FROM templates WHERE name = $1 AND active = true',
      [templateName]
    );
    return result.rows[0] || null;
  } finally {
    client.release();
  }
}

exports.handler = async (event) => {
  try {
    const userId = event.requestContext?.authorizer?.claims?.sub || 'anonymous';
    const templateName = event.queryStringParameters?.template;

    if (!templateName) {
      return { statusCode: 400, body: JSON.stringify({ error: 'template parameter required' }) };
    }

    // Validate template exists in database
    const metadata = await getTemplateMetadata(templateName);
    if (!metadata) {
      await logAccess(userId, templateName, 'NOT_FOUND');
      return { statusCode: 404, body: JSON.stringify({ error: 'Template not found' }) };
    }

    // Load template file from disk
    const templatePath = path.join(TEMPLATES_DIR, templateName);

    // Basic extension check
    if (!templateName.endsWith('.html') && !templateName.endsWith('.hbs')) {
      return { statusCode: 400, body: JSON.stringify({ error: 'Invalid template type' }) };
    }

    const content = fs.readFileSync(templatePath, 'utf-8');

    await logAccess(userId, templateName, 'READ');

    return {
      statusCode: 200,
      headers: { 'Content-Type': 'text/html' },
      body: content
    };
  } catch (err) {
    console.error('Handler error:', err.message);
    return { statusCode: 500, body: JSON.stringify({ error: 'Internal server error' }) };
  }
};
